INSERT INTO complaint_codes (code, category, description, initial_owner, priority_guidance) VALUES ('CMP-004', 'Alarm / warning failure', 'Alarm absent, too quiet, false alarm or cannot silence as designed', 'Clinical user + Biomedical Engineer', 'High/Critical') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), initial_owner=VALUES(initial_owner), priority_guidance=VALUES(priority_guidance);
