INSERT INTO complaint_codes (code, category, description, initial_owner, priority_guidance) VALUES ('CMP-006', 'Battery / charging', 'Battery not charging, short runtime, battery warning', 'Clinical user + Biomedical Engineer', 'Medium–High') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), initial_owner=VALUES(initial_owner), priority_guidance=VALUES(priority_guidance);
