INSERT INTO complaint_codes (code, category, description, initial_owner, priority_guidance) VALUES ('CMP-008', 'Mechanical / movement', 'Motor, brake, rail, arm, table or actuator failure', 'Clinical user + Biomedical Engineer / Facilities', 'High/Critical') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), initial_owner=VALUES(initial_owner), priority_guidance=VALUES(priority_guidance);
